package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The sheets and their "today". A sheet starts with the real date the first time it is loaded;
 * from then on {@link #today(String)} is the only date the app uses for that sheet — never the
 * real clock.
 */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today, starting the sheet at the real date when it has never been used. */
    public LocalDate today(String sheetId) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, ? FROM DUAL "
                + "WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                sheetId, Date.valueOf(LocalDate.now()), sheetId);
        return jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId)
                .toLocalDate();
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, Date.valueOf(today));
    }
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { asString, useSearchParam } from '../../url/useSearchParam';

/**
 * Who is signed in and which sheet is active. Both live in the URL (`user`, `sheet`) like any other
 * state that outlives a click; every feature that needs them reads them from here.
 */
export function useCurrentUser() {
  return useSearchParam('user', asString);
}

export function useCurrentSheet() {
  return useSearchParam('sheet', asString);
}
-- One row per sheet that has been loaded. `today` is the sheet's own date: every date-dependent
-- decision and every default date on the sheet uses it, never the real clock.
CREATE TABLE sheet (
    id    VARCHAR(200) PRIMARY KEY,
    today DATE         NOT NULL
);
-- The people on a sheet, listed in the order they were added (by id). `grade` is one of A, B, C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    name     VARCHAR(500) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's name is unique on its sheet, compared without case and ignoring surrounding spaces.
-- Names are stored trimmed; `name_key` is the form they are compared in.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(500) GENERATED ALWAYS AS (LOWER(TRIM(name)));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person's claims, listed newest first (by id). `amount` is 0.00 or more, two decimals;
-- `claim_date` defaults to the sheet's today when the claim is made; `note` may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL,
    person_id  BIGINT        NOT NULL REFERENCES person (id),
    amount     DECIMAL(14,2) NOT NULL CHECK (amount >= 0),
    claim_date DATE          NOT NULL,
    note       VARCHAR(2000) NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);

