import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Runs after the claim is saved, so a refused edit writes no audit line. */
public class RecordClaimEdited {
    public void record(@Val ClaimValues values, @Val Claim claim, People people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record("CLAIM_EDITED sheet=" + claim.getSheetId() + " by=" + values.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate());
    }
}
EOF
cd resources/officefloor/rest/api/sheets/{sheetId}
python3 - <<'EOF'
import re
for f,cls in [("people.POST.yml","person.RecordPersonAdded"),("people/{personId}.PUT.yml","person.RecordPersonEdited"),
              ("claims/{claimId}.PUT.yml","claim.RecordClaimEdited"),("people/{personId}/claims.POST.yml","claim.RecordClaimAdded")]:
    s=open(f).read()
    s=s.replace("  govern: [ transaction ]\n  next: respond\nrespond:",
      "  govern: [ transaction ]\n  next: record\n# Audit only once the change is saved: a refused change writes no line.\nrecord:\n  class: net.officefloor.hq.app.%s\n  govern: [ transaction ]\n  next: respond\nrespond:"%cls,1)
    assert "record:" in s, f
    open(f,"w").write(s)
EOF
cat people.POST.yml

